import React from "react";
import { useLocation, useNavigate } from "react-router-dom";
import "../styles/UserGig.css";

const UserGig = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const gig = location.state?.gig;

  if (!gig) return <p style={{ textAlign: "center" }}>No gig selected.</p>;

  return (
    <div className="gig-details-container">
      <h2 className="gig-title">GIG POSTING</h2>

      <div className="gig-form">
        <label>Title</label>
        <input type="text" value={gig.title} readOnly />

        <label>Gig Type</label>
        <input type="text" value={gig.gigType} readOnly />

        <label>Genre</label>
        <input type="text" value={Array.isArray(gig.genre) ? gig.genre.join(", ") : gig.genre} readOnly />

        <label>City</label>
        <input type="text" value={gig.city} readOnly />

        <label>Description</label>
        <textarea value={gig.description} rows="4" readOnly />

        <label>Date Posted</label>
        <input type="text" value={gig.createdAt?.split("T")[0]} readOnly />

        <label>Expires</label>
        <input type="text" value={gig.expiryDate?.split("T")[0]} readOnly />

        <label>Posted By</label>
        <input type="text" value={gig.username} readOnly />

        <button onClick={() => navigate(`/profile/${gig.userId}`)}>
          View User Profile
        </button>
      </div>
    </div>
  );
};

export default UserGig;
